import React from "react";
import { palette } from "../theme/palette";
import { GarlandSwag, Leaf, MarigoldStrand } from "../props/Florals";

/*
 * Sets for the pre-wedding celebrations (Engagement, Haldi & Mehendi, Sangeet),
 * drawn in 1080×1920 scene space. Plain SVG fills + alpha gradients only.
 */

/* ───────────── Cusped (multi-foil) Mughal arch ───────────── */

type P = [number, number];
const cubic = (p0: P, p1: P, p2: P, p3: P, t: number): P => {
  const u = 1 - t;
  return [
    u * u * u * p0[0] + 3 * u * u * t * p1[0] + 3 * u * t * t * p2[0] + t * t * t * p3[0],
    u * u * u * p0[1] + 3 * u * u * t * p1[1] + 3 * u * t * t * p2[1] + t * t * t * p3[1],
  ];
};

/**
 * Outline of a cusped arch opening: straight jambs from `floor` up to `spring`, then a pointed
 * arch made of `lobes` foils per side meeting at the apex.
 */
export const cuspedArchPath = (cx: number, w: number, spring: number, apex: number, floor: number, lobes = 4): string => {
  const x0 = cx - w / 2;
  const x1 = cx + w / 2;
  const h = spring - apex;
  const left: P[] = [];
  for (let i = 0; i <= lobes; i++)
    left.push(cubic([x0, spring], [x0, spring - h * 0.62], [cx - w * 0.2, apex + h * 0.16], [cx, apex], i / lobes));
  const right: P[] = left
    .slice(0, -1)
    .reverse()
    .map(([x, y]) => [2 * cx - x, y] as P);
  const pts = [...left, ...right];
  let d = `M${x0} ${floor} L${x0} ${spring}`;
  for (let i = 1; i < pts.length; i++) {
    const [ax, ay] = pts[i - 1];
    const [bx, by] = pts[i];
    const r = Math.hypot(bx - ax, by - ay) * 0.6;
    d += ` A${r.toFixed(1)} ${r.toFixed(1)} 0 0 1 ${bx.toFixed(1)} ${by.toFixed(1)}`;
  }
  d += ` L${x1} ${floor} Z`;
  return d;
};

/** A niche: recessed fill + foil edge + inner hairline. */
export const ArchNiche: React.FC<{
  cx: number;
  w: number;
  spring: number;
  apex: number;
  floor: number;
  fill: string;
  lobes?: number;
  inner?: string;
  edge?: number;
}> = ({ cx, w, spring, apex, floor, fill, lobes = 4, inner, edge = 1 }) => {
  const outer = cuspedArchPath(cx, w, spring, apex, floor, lobes);
  const innerPath = cuspedArchPath(cx, w - 34, spring + 10, apex + 20, floor, lobes);
  return (
    <g>
      <path d={cuspedArchPath(cx, w + 26, spring - 6, apex - 18, floor, lobes)} fill="#000" opacity={0.1} />
      <path d={outer} fill={fill} />
      {inner ? <path d={innerPath} fill={inner} /> : null}
      <path d={outer} fill="none" stroke="url(#foil)" strokeWidth={4 * edge} />
      <path d={innerPath} fill="none" stroke={palette.goldLight} strokeWidth={1.2 * edge} opacity={0.7} />
    </g>
  );
};

/* ───────────── String lights ───────────── */

/** Catenary wire with warm bulbs; `on` 0→1 lights them left→right, twinkling gently. */
export const StringLights: React.FC<{
  from: P;
  to: P;
  sag: number;
  count: number;
  frame: number;
  on?: number;
  seed?: number;
  bulb?: string;
  glow?: string;
  size?: number;
}> = ({ from, to, sag, count, frame, on = 1, seed = 0, bulb = "#FFE6A8", glow = "#FFD27A", size = 1 }) => {
  const [x0, y0] = from;
  const [x1, y1] = to;
  const cx = (x0 + x1) / 2;
  const cy = (y0 + y1) / 2 + sag * 2;
  const pt = (t: number): P => {
    const u = 1 - t;
    return [u * u * x0 + 2 * u * t * cx + t * t * x1, u * u * y0 + 2 * u * t * cy + t * t * y1];
  };
  return (
    <g>
      <path d={`M${x0} ${y0} Q${cx} ${cy} ${x1} ${y1}`} fill="none" stroke="#2A1A14" strokeWidth={1.6} opacity={0.75} />
      {new Array(count).fill(0).map((_, i) => {
        const t = (i + 0.5) / count;
        const [x, y] = pt(t);
        const lit = Math.min(1, Math.max(0, on * (count + 3) - i) / 3);
        const tw = 0.72 + 0.28 * Math.sin(frame / (9 + ((i * 7 + seed) % 6)) + i * 1.7 + seed);
        const a = lit * tw;
        return (
          <g key={i} transform={`translate(${x} ${y}) scale(${size})`}>
            <path d="M0 0 L0 6" stroke="#2A1A14" strokeWidth={1.2} />
            <circle cx={0} cy={18} r={26} fill={glow} opacity={0.1 * a} />
            <circle cx={0} cy={18} r={14} fill={glow} opacity={0.22 * a} />
            <rect x={-3.5} y={4} width={7} height={6} rx={1} fill={palette.goldDeep} />
            <ellipse cx={0} cy={17} rx={6} ry={8} fill={lit > 0 ? bulb : "#8C7A60"} opacity={0.45 + 0.55 * a} />
            <ellipse cx={-2} cy={14} rx={1.6} ry={3} fill="#FFFFFF" opacity={0.6 * a} />
          </g>
        );
      })}
    </g>
  );
};

/* ───────────── Hanging paper planet & stars ───────────── */

/** A small red paper planet on a thread from (x, top); `swing` in degrees. */
export const HangingPlanet: React.FC<{ x: number; top: number; length: number; r: number; swing: number }> = ({ x, top, length, r, swing }) => (
  <g transform={`rotate(${swing} ${x} ${top})`}>
    <path d={`M${x} ${top} L${x} ${top + length - r}`} stroke={palette.goldDeep} strokeWidth={1.2} />
    <circle cx={x} cy={top} r={3.5} fill="url(#foil)" />
    <circle cx={x + 4} cy={top + length + 5} r={r} fill="#000" opacity={0.18} />
    <circle cx={x} cy={top + length} r={r} fill="#A63A2E" />
    <path
      d={`M${x - r} ${top + length} A${r} ${r} 0 0 0 ${x + r} ${top + length} A${r * 1.1} ${r * 0.7} 0 0 1 ${x - r} ${top + length} Z`}
      fill="#7E2622"
      opacity={0.55}
    />
    <circle cx={x - r * 0.35} cy={top + length - r * 0.3} r={r * 0.2} fill="#8C2C24" />
    <circle cx={x + r * 0.35} cy={top + length + r * 0.15} r={r * 0.13} fill="#8C2C24" />
    <circle cx={x + r * 0.05} cy={top + length - r * 0.62} r={r * 0.09} fill="#8C2C24" />
    <path d={`M${x - r * 0.62} ${top + length - r * 0.52} A${r * 0.8} ${r * 0.8} 0 0 1 ${x - r * 0.05} ${top + length - r * 0.86}`} fill="none" stroke="#F0A38A" strokeWidth={2.4} strokeLinecap="round" opacity={0.7} />
    <circle cx={x} cy={top + length} r={r} fill="none" stroke="url(#foil)" strokeWidth={2} />
  </g>
);

export const HangingStar: React.FC<{ x: number; top: number; length: number; r: number; swing: number; opacity?: number }> = ({
  x,
  top,
  length,
  r,
  swing,
  opacity = 1,
}) => {
  const pts = new Array(10)
    .fill(0)
    .map((_, i) => {
      const a = (i / 10) * Math.PI * 2 - Math.PI / 2;
      const rr = i % 2 ? r * 0.45 : r;
      return `${(x + Math.cos(a) * rr).toFixed(1)} ${(top + length + Math.sin(a) * rr).toFixed(1)}`;
    })
    .join(" L");
  return (
    <g transform={`rotate(${swing} ${x} ${top})`} opacity={opacity}>
      <path d={`M${x} ${top} L${x} ${top + length - r}`} stroke={palette.goldDeep} strokeWidth={1} opacity={0.8} />
      <path d={`M${pts} Z`} fill="url(#foil)" />
    </g>
  );
};

/* ───────────── Marigold toran ───────────── */

/** Marigold toran across the top: swags, mango leaves and hanging ladis. `grow` 0→1. */
export const Toran: React.FC<{ y: number; x0?: number; x1?: number; grow: number; swags?: number; seed?: string; strandLen?: number }> = ({
  y,
  x0 = -20,
  x1 = 1100,
  grow,
  swags = 4,
  seed = "toran",
  strandLen = 150,
}) => {
  const w = (x1 - x0) / swags;
  return (
    <g>
      <rect x={x0} y={y - 16} width={(x1 - x0) * grow} height={18} fill={palette.marigoldDeep} />
      <rect x={x0} y={y - 16} width={(x1 - x0) * grow} height={3} fill={palette.goldLight} opacity={0.8} />
      {new Array(Math.ceil(((x1 - x0) / 34) * grow)).fill(0).map((_, i) => (
        <Leaf key={i} x={x0 + 10 + i * 34} y={y} rot={80 + (i % 2 ? 14 : -14)} s={2.2} color={i % 2 ? palette.green : palette.greenDeep} />
      ))}
      {new Array(swags).fill(0).map((_, i) => {
        const g = Math.min(1, Math.max(0, grow * swags - i));
        if (g <= 0) return null;
        const a: P = [x0 + i * w, y];
        const b: P = [x0 + (i + 1) * w, y];
        return (
          <g key={i} opacity={Math.min(1, g * 2)}>
            <GarlandSwag from={a} to={b} sag={36 * g} r={13} seed={`${seed}-${i}`} tones={["orange", "yellow", "orange", "orange"]} />
            <g transform={`translate(0 ${(1 - g) * -40})`}>
              <MarigoldStrand x={b[0]} y={y + 4} length={strandLen * g} r={11} seed={`${seed}-s${i}`} />
            </g>
          </g>
        );
      })}
    </g>
  );
};

/* ───────────── Stage: curtains, valance, shadow screen, beams ───────────── */

/**
 * Side curtain with folds, gathered by a gold tie-back. `side` = which frame edge it hangs from;
 * `open` 0 (drawn across to the centre) → 1 (tied back at the side).
 */
export const SideCurtain: React.FC<{ side: "left" | "right"; open: number; top: number; floor: number; color: string; shade: string; id: string }> = ({
  side,
  open,
  top,
  floor,
  color,
  shade,
  id,
}) => {
  const closedW = 560;
  const openW = 190;
  const wTop = closedW + (openW - closedW) * open;
  const tieY = top + (floor - top) * 0.58;
  const tieW = wTop * (1 - 0.55 * open);
  const hemW = wTop * (1 + 0.15 * open);
  const m = (x: number) => (side === "left" ? x : 1080 - x);
  const d = [
    `M${m(-20)} ${top}`,
    `L${m(wTop)} ${top}`,
    `C${m(wTop + 10)} ${top + 200} ${m(tieW + 20)} ${tieY - 180} ${m(tieW)} ${tieY}`,
    `C${m(tieW + 6)} ${tieY + 140} ${m(hemW)} ${floor - 180} ${m(hemW)} ${floor}`,
    `L${m(-20)} ${floor} Z`,
  ].join(" ");
  const folds = 7;
  return (
    <g>
      <defs>
        <linearGradient id={id} x1="0" y1="0" x2="1" y2="0">
          {new Array(folds * 2 + 1).fill(0).map((_, i) => (
            <stop key={i} offset={i / (folds * 2)} stopColor={i % 2 ? color : shade} />
          ))}
        </linearGradient>
      </defs>
      <path d={d} fill="#000" opacity={0.25} transform={`translate(${side === "left" ? 10 : -10} 0)`} />
      <path d={d} fill={`url(#${id})`} />
      {/* gold braid on the leading edge */}
      <path
        d={`M${m(wTop)} ${top} C${m(wTop + 10)} ${top + 200} ${m(tieW + 20)} ${tieY - 180} ${m(tieW)} ${tieY} C${m(tieW + 6)} ${tieY + 140} ${m(hemW)} ${floor - 180} ${m(hemW)} ${floor}`}
        fill="none"
        stroke="url(#foil)"
        strokeWidth={5}
      />
      {/* tie-back with tassel */}
      <g opacity={open}>
        <path d={`M${m(-10)} ${tieY - 12} Q${m(tieW * 0.5)} ${tieY + 18} ${m(tieW + 6)} ${tieY - 4}`} fill="none" stroke="url(#foil)" strokeWidth={7} />
        <circle cx={m(tieW + 6)} cy={tieY - 2} r={9} fill="url(#foil)" />
        <path d={`M${m(tieW + 1)} ${tieY + 4} L${m(tieW - 5)} ${tieY + 50} L${m(tieW + 17)} ${tieY + 50} L${m(tieW + 11)} ${tieY + 4} Z`} fill={palette.gold} />
      </g>
    </g>
  );
};

/** Proscenium valance: layered swags with gold scallop trim and tassels. */
export const Valance: React.FC<{ y: number; color: string; shade: string; swags?: number }> = ({ y, color, shade, swags = 5 }) => {
  const w = 1080 / swags;
  return (
    <g>
      <rect x={0} y={0} width={1080} height={y} fill={shade} />
      <rect x={0} y={y - 24} width={1080} height={4} fill={palette.gold} />
      {new Array(swags).fill(0).map((_, i) => {
        const x0 = i * w;
        const x1 = x0 + w;
        const mid = (x0 + x1) / 2;
        return (
          <g key={i}>
            <path d={`M${x0 - 6} ${y - 30} Q${mid} ${y + 110} ${x1 + 6} ${y - 30} Z`} fill={shade} />
            <path d={`M${x0 - 6} ${y - 30} Q${mid} ${y + 86} ${x1 + 6} ${y - 30} Q${mid} ${y + 40} ${x0 - 6} ${y - 30} Z`} fill={color} />
            <path d={`M${x0 - 6} ${y - 30} Q${mid} ${y + 110} ${x1 + 6} ${y - 30}`} fill="none" stroke="url(#foil)" strokeWidth={3} />
            {/* scallop trim */}
            {new Array(7).fill(0).map((_, k) => {
              const t = (k + 0.5) / 7;
              const u = 1 - t;
              const sx = u * u * (x0 - 6) + 2 * u * t * mid + t * t * (x1 + 6);
              const sy = u * u * (y - 30) + 2 * u * t * (y + 110) + t * t * (y - 30);
              return <path key={k} d={`M${sx - 9} ${sy} A9 9 0 0 0 ${sx + 9} ${sy}`} fill={palette.goldLight} opacity={0.85} />;
            })}
            <path d={`M${x1} ${y - 30} L${x1} ${y + 30}`} stroke={palette.gold} strokeWidth={2} />
            <circle cx={x1} cy={y + 30} r={7} fill="url(#foil)" />
            <path d={`M${x1 - 5} ${y + 34} L${x1 - 9} ${y + 72} L${x1 + 9} ${y + 72} L${x1 + 5} ${y + 34} Z`} fill={palette.gold} />
          </g>
        );
      })}
    </g>
  );
};

/** Backlit shadow-puppet screen: warm glow inside a gold frame. `glow` 0→1. */
export const ShadowScreen: React.FC<{ x: number; y: number; w: number; h: number; glow: number; id: string }> = ({ x, y, w, h, glow, id }) => (
  <g>
    <defs>
      <radialGradient id={id} cx="0.5" cy="0.62" r="0.7">
        <stop offset="0" stopColor="#FFE9B8" />
        <stop offset="0.45" stopColor="#F4C77E" />
        <stop offset="1" stopColor="#C4804A" />
      </radialGradient>
    </defs>
    <rect x={x - 16} y={y - 16} width={w + 32} height={h + 32} fill="#1E1418" />
    <rect x={x} y={y} width={w} height={h} fill="#5A3A3A" />
    <rect x={x} y={y} width={w} height={h} fill={`url(#${id})`} opacity={glow} />
    <rect x={x - 10} y={y - 10} width={w + 20} height={h + 20} fill="none" stroke="url(#foil)" strokeWidth={5} />
    <rect x={x - 2} y={y - 2} width={w + 4} height={h + 4} fill="none" stroke={palette.goldDeep} strokeWidth={1.4} />
  </g>
);

/**
 * Soft spotlight cone from `src` to a pool centred on `dst`, as alpha gradients (no blend modes).
 * Three nested cones feather the edge.
 */
export const SpotBeam: React.FC<{ src: P; dst: P; spread: number; intensity: number; id: string; color?: string }> = ({
  src,
  dst,
  spread,
  intensity,
  id,
  color = "#FFE3B0",
}) => {
  const [sx, sy] = src;
  const [dx, dy] = dst;
  const ang = Math.atan2(dy - sy, dx - sx);
  const nx = -Math.sin(ang);
  const ny = Math.cos(ang);
  const cone = (k: number) => {
    const wS = 14 * k;
    const wD = spread * k;
    return `M${sx + nx * wS} ${sy + ny * wS} L${dx + nx * wD} ${dy + ny * wD} L${dx - nx * wD} ${dy - ny * wD} L${sx - nx * wS} ${sy - ny * wS} Z`;
  };
  return (
    <g>
      <defs>
        <linearGradient id={id} gradientUnits="userSpaceOnUse" x1={sx} y1={sy} x2={dx} y2={dy}>
          <stop offset="0" stopColor={color} stopOpacity={0.55} />
          <stop offset="0.5" stopColor={color} stopOpacity={0.28} />
          <stop offset="1" stopColor={color} stopOpacity={0.12} />
        </linearGradient>
        <radialGradient id={`${id}-pool`}>
          <stop offset="0" stopColor={color} stopOpacity={0.45} />
          <stop offset="0.5" stopColor={color} stopOpacity={0.2} />
          <stop offset="1" stopColor={color} stopOpacity={0} />
        </radialGradient>
      </defs>
      <g opacity={intensity}>
        <path d={cone(1.25)} fill={`url(#${id})`} opacity={0.25} />
        <path d={cone(1)} fill={`url(#${id})`} opacity={0.35} />
        <path d={cone(0.72)} fill={`url(#${id})`} opacity={0.45} />
        <ellipse cx={dx} cy={dy} rx={spread * 1.3} ry={spread * 0.32} fill={`url(#${id}-pool)`} />
      </g>
    </g>
  );
};
